package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import java.io.*;
import java.net.*;
import java.util.*;
public class PublicMediaHttpTest {
 static class Reply extends HttpURLConnection {final int status;final String location;final byte[] body;boolean disconnected;Reply(URL url,int status,String location,byte[] body){super(url);this.status=status;this.location=location;this.body=body;}public void connect(){}public boolean usingProxy(){return false;}public void disconnect(){disconnected=true;}public int getResponseCode(){return status;}public String getHeaderField(String name){return name.equals("Location")?location:null;}public String getContentType(){return "text/html";}public InputStream getInputStream(){return new ByteArrayInputStream(body);}}
 @Test public void shortRedirectStaysHttpsAndInTiktok()throws Exception{List<Reply> replies=new ArrayList<>();PublicMediaHttp.Page page=PublicMediaHttp.read("https://vt.tiktok.com/ZSg42qGJc/",true,url->{Reply r=new Reply(url,replies.isEmpty()?302:200,replies.isEmpty()?"https://www.tiktok.com/@onda/video/7412345678901234567":null,new byte[]{1,2});replies.add(r);return r;});assertTrue(page.url.contains("/video/"));assertEquals(2,replies.size());for(Reply reply:replies)assertEquals(PublicMediaHttp.TIKTOK_AGENT,reply.getRequestProperty("User-Agent"));assertTrue(replies.get(0).disconnected);for(String location:new String[]{"http://www.tiktok.com/x","https://evil.example.org/x"}){int[] opens={0};try{PublicMediaHttp.read("https://vt.tiktok.com/ZSg42qGJc/",true,url->{opens[0]++;return new Reply(url,302,location,new byte[0]);});fail();}catch(IOException expected){assertEquals(1,opens[0]);}}}
 @Test public void prefixReadDoesNotDownloadFullLargeMedia()throws Exception{Reply[] reply={null};PublicMediaHttp.Page page=PublicMediaHttp.read("https://cdn.example.org/a.mp4",false,url->reply[0]=new Reply(url,200,null,new byte[1000000]));assertEquals(65536,page.bytes.length);assertEquals(PublicMediaHttp.AGENT,reply[0].getRequestProperty("User-Agent"));assertEquals("bytes=0-65535",reply[0].getRequestProperty("Range"));assertTrue(reply[0].disconnected);}
 @Test public void rejectInternalAddressesAndFakeMedia()throws Exception{for(String ip:new String[]{"127.0.0.1","10.1.2.3","192.168.1.1","172.20.1.1","169.254.169.254","100.64.0.1","0.0.0.0","224.0.0.1","::1","fc00::1"})assertFalse(ip,PublicMediaHttp.publicAddress(InetAddress.getByName(ip)));assertTrue(PublicMediaHttp.publicAddress(InetAddress.getByName("8.8.8.8")));assertFalse(PublicMediaHttp.mediaHeader("<html>login</html>".getBytes(),"mp4"));assertTrue(PublicMediaHttp.mediaHeader(new byte[]{0,0,0,20,'f','t','y','p','i','s','o','m'},"mp4"));assertTrue(PublicMediaHttp.mediaHeader("ID3test".getBytes(),"mp3"));}
 @Test public void redirectLoopsAreBounded()throws Exception{int[] opens={0};try{PublicMediaHttp.read("https://vt.tiktok.com/ZSg42qGJc/",true,url->{opens[0]++;return new Reply(url,302,url.toString(),new byte[0]);});fail();}catch(IOException expected){assertEquals(7,opens[0]);}}
 @Test public void videoProbeKeepsDesktopAgentAndReferer()throws Exception{Reply[] reply={null};String page="https://www.tiktok.com/@onda/video/7412345678901234567";PublicMediaHttp.read("https://cdn.example.org/a.mp4",false,page,url->reply[0]=new Reply(url,206,null,new byte[65536]));assertEquals(PublicMediaHttp.TIKTOK_AGENT,reply[0].getRequestProperty("User-Agent"));assertEquals(page,reply[0].getRequestProperty("Referer"));assertEquals("bytes=0-65535",reply[0].getRequestProperty("Range"));}

}
